const cleanup = stepResult(merge, 'cleanup')
log(`Cleanup${a.batchTag}: ${cleanup ? (cleanup.exit_code === 0 ? 'done' : `exited ${cleanup.exit_code}`) : 'step did not run'}`)
// `worktrees cleanup` prints {"cleaned": {..., "preserved_with_commits": [...]}} —
